//! In-memory rolling market state and score recomputation.
use std::collections::{HashMap,VecDeque};use std::sync::Mutex;use score_engine::{MarketRegime,ScoreInput,ScoreWeights};use shared::{Candle,FundingRate,OpenInterest,OrderBookSnapshot,Score};const CANDLE_HISTORY:usize=60;
#[derive(Debug,Clone,Copy)]pub struct SpecializedSnapshot{pub sweep:score_engine::SweepResult,pub shock:score_engine::ShockResult,pub derivatives_stress:score_engine::DerivativesStress,pub conflict:score_engine::ConflictResult,pub regime_transition:score_engine::RegimeTransition,pub cross_market:score_engine::CrossMarketResult}
struct SymbolState{candles:VecDeque<Candle>,order_book:Option<OrderBookSnapshot>,funding_rate:Option<FundingRate>,open_interest:VecDeque<OpenInterest>,latest_score:Option<Score>,previous_regime:Option<MarketRegime>}
impl SymbolState{fn new()->Self{Self{candles:VecDeque::with_capacity(CANDLE_HISTORY),order_book:None,funding_rate:None,open_interest:VecDeque::with_capacity(2),latest_score:None,previous_regime:None}}fn recompute(&mut self,symbol:&str,weights:&ScoreWeights)->Option<Score>{if self.candles.is_empty(){return None}let order_book=self.order_book.clone().unwrap_or_else(||OrderBookSnapshot{symbol:symbol.into(),timestamp:0,bids:vec![],asks:vec![]});let funding_rate=self.funding_rate.clone().unwrap_or_else(||FundingRate{symbol:symbol.into(),timestamp:0,rate:0.0});let input=ScoreInput{candles:self.candles.iter().cloned().collect(),order_book,funding_rate};let score=score_engine::calculate(&input,weights);self.latest_score=Some(score.clone());Some(score)}}
pub struct MarketState{symbols:Mutex<HashMap<String,SymbolState>>,weights:ScoreWeights}
impl MarketState{pub fn new(weights:ScoreWeights)->Self{Self{symbols:Mutex::new(HashMap::new()),weights}}pub fn latest_score(&self,symbol:&str)->Option<Score>{self.symbols.lock().expect("market state lock poisoned").get(symbol).and_then(|s|s.latest_score.clone())}pub fn latest_price(&self,symbol:&str)->Option<f64>{self.symbols.lock().ok()?.get(symbol)?.candles.back().map(|c|c.close)}pub fn ingest_candle(&self,candle:Candle)->Option<Score>{let mut symbols=self.symbols.lock().expect("market state lock poisoned");let state=symbols.entry(candle.symbol.clone()).or_insert_with(SymbolState::new);if let Some(last)=state.candles.back_mut(){if last.interval==candle.interval&&last.open_time==candle.open_time{*last=candle.clone();return state.recompute(&candle.symbol,&self.weights)}}state.candles.push_back(candle.clone());if state.candles.len()>CANDLE_HISTORY{state.candles.pop_front();}state.recompute(&candle.symbol,&self.weights)}pub fn ingest_order_book(&self,snapshot:OrderBookSnapshot)->Option<Score>{let mut symbols=self.symbols.lock().expect("market state lock poisoned");let state=symbols.entry(snapshot.symbol.clone()).or_insert_with(SymbolState::new);let symbol=snapshot.symbol.clone();state.order_book=Some(snapshot);state.recompute(&symbol,&self.weights)}pub fn ingest_funding_rate(&self,rate:FundingRate)->Option<Score>{let mut symbols=self.symbols.lock().expect("market state lock poisoned");let state=symbols.entry(rate.symbol.clone()).or_insert_with(SymbolState::new);let symbol=rate.symbol.clone();state.funding_rate=Some(rate);state.recompute(&symbol,&self.weights)}pub fn ingest_open_interest(&self,oi:OpenInterest)->Option<Score>{let mut symbols=self.symbols.lock().expect("market state lock poisoned");let state=symbols.entry(oi.symbol.clone()).or_insert_with(SymbolState::new);let symbol=oi.symbol.clone();state.open_interest.push_back(oi);while state.open_interest.len()>2{state.open_interest.pop_front();}state.recompute(&symbol,&self.weights)}pub fn latest_derivatives(&self,symbol:&str)->Option<score_engine::DerivativesResult>{let symbols=self.symbols.lock().ok()?;let state=symbols.get(symbol)?;self.latest_derivatives_unlocked(state)}pub fn specialized(&self,symbol:&str,decision:score_engine::Decision)->Option<SpecializedSnapshot>{let mut symbols=self.symbols.lock().ok()?;let reference=if symbol!="BTCUSDT"{symbols.get("BTCUSDT").map(|s|returns(&s.candles))}else{symbols.get("ETHUSDT").map(|s|returns(&s.candles))};let state=symbols.get_mut(symbol)?;let candles:Vec<Candle>=state.candles.iter().cloned().collect();let sweep=score_engine::liquidity_sweep(&candles);let shock=score_engine::market_shock(&candles);let derivatives=self.latest_derivatives_unlocked(state);let derivatives_stress=score_engine::derivatives_stress(derivatives.as_ref());let liquidity=state.order_book.as_ref().map(score_engine::liquidity_order_flow);let composite=state.latest_score.as_ref()?.value;let conflict=score_engine::signal_conflict(decision,composite,derivatives.as_ref().map(|d|d.derivatives_score),liquidity.as_ref());let current=score_engine::market_regime(&candles).regime;let regime_transition=score_engine::regime_transition(state.previous_regime,current,shock.score);state.previous_regime=Some(current);let primary=returns(&state.candles);let cross_market=reference.as_ref().map_or(score_engine::CrossMarketResult{score:0.0,divergence:0.0},|r|score_engine::cross_market(&primary,r));Some(SpecializedSnapshot{sweep,shock,derivatives_stress,conflict,regime_transition,cross_market})}fn latest_derivatives_unlocked(&self,state:&SymbolState)->Option<score_engine::DerivativesResult>{let funding=state.funding_rate.as_ref()?;let current=state.open_interest.back();let previous=if state.open_interest.len()>=2{state.open_interest.front()}else{None};let price_change=if state.candles.len()>=2{let a=&state.candles[state.candles.len()-2];let b=state.candles.back()?;if a.close!=0.0{(b.close/a.close-1.0)*100.0}else{0.0}}else{0.0};Some(score_engine::derivatives(previous,current,funding,price_change))}pub fn intelligence(&self,symbol:&str)->Option<score_engine::IntelligenceSnapshot>{let score=self.latest_score(symbol)?;let derivatives=self.latest_derivatives(symbol);Some(score_engine::intelligence_snapshot(&score,derivatives.as_ref()))}}
fn returns(c:&VecDeque<Candle>)->Vec<f64>{c.iter().collect::<Vec<_>>().windows(2).filter_map(|w|(w[0].close>0.0).then_some((w[1].close/w[0].close-1.0)*100.0)).collect()}
#[cfg(test)]mod tests{use super::*;fn candle(symbol:&str,t:i64)->Candle{Candle{symbol:symbol.into(),interval:"1m".into(),open_time:t,close_time:t+60000,open:100.0,high:100.0,low:100.0,close:100.0,volume:100.0}}#[test]fn scores_after_first_candle(){let s=MarketState::new(ScoreWeights::default());s.ingest_candle(candle("BTCUSDT",0));assert!(s.latest_score("BTCUSDT").is_some());assert_eq!(s.latest_price("BTCUSDT"),Some(100.0));}#[test]fn keeps_two_oi_points(){let s=MarketState::new(ScoreWeights::default());for i in 0..3{s.ingest_open_interest(OpenInterest{symbol:"BTCUSDT".into(),timestamp:i,value:100.0+i as f64});}let x=s.symbols.lock().unwrap();assert_eq!(x.get("BTCUSDT").unwrap().open_interest.len(),2);}#[test]fn builds_intelligence_snapshot(){let s=MarketState::new(ScoreWeights::default());s.ingest_candle(candle("BTCUSDT",0));assert!(s.intelligence("BTCUSDT").is_some());}}
